import { Routes, Route } from 'react-router-dom';
import Layout from './components/Layout';
import Landing from './pages/Landing';
import Login from './pages/LandignPage/Landing';
import AdminDashboard from './pages/admin/AdminDashboard';
import ListUsers from './pages/admin/users/ListUsers';
import AddUser from './pages/admin/users/AddUser';
import ListRoles from './pages/admin/roles/ListRoles';
import AddRole from './pages/admin/roles/AddRole';
import ListPermissions from './pages/admin/permissions/ListPermissions';
import AddPermission from './pages/admin/permissions/AddPermission';
import ListDepartments from './pages/admin/departments/ListDepartments';
import AddDepartment from './pages/admin/departments/AddDepartment';
import JournalDashboard from './pages/modules/journal/JournalDashboard';
import EbookDashboard from './pages/modules/ebooks/EbookDashboard';
import LibraryDashboard from './pages/modules/library/LibraryDashboard';
import WikipediaDashboard from './pages/modules/wikipedia/WikipediaDashboard';
import RepositoryDashboard from './pages/modules/repository/RepositoryDashboard';
import ResearchersDashboard from './pages/modules/researchers/ResearchersDashboard';

function AppRoutes({ hideSidebar }) {
  return (
    <Routes>
      {/* Routes without Layout */}
      <Route path="/" element={<Landing />} />
      <Route path="/auth/login" element={<Login />} />

      {/* Routes with Layout */}
      <Route element={<Layout hideSidebar={hideSidebar} />}>
        <Route path="/admin/dashboard" element={<AdminDashboard />} />
        
        <Route path="/admin/users" element={<ListUsers />} />
        <Route path="/admin/users/add" element={<AddUser />} />
        <Route path="/roles" element={<ListRoles />} />
        <Route path="/roles/add" element={<AddRole />} />
        <Route path="/permissions" element={<ListPermissions />} />
        <Route path="/permissions/add" element={<AddPermission />} />
        <Route path="/departments" element={<ListDepartments />} />
        <Route path="/department/add" element={<AddDepartment />} />

        {/* MODULE ROUTES */}
        <Route path="/journal" element={<JournalDashboard />} />
        <Route path="/ebooks" element={<EbookDashboard />} />
        <Route path="/library" element={<LibraryDashboard />} />
        <Route path="/wikipedia" element={<WikipediaDashboard />} />
        <Route path="/repository" element={<RepositoryDashboard />} />
        <Route path="/researchers" element={<ResearchersDashboard />} />
      </Route>
    </Routes>
  );
}

export default AppRoutes;
